# MGS web — FeniXVOID · Project Ravenlight
BANNER = 'echo\necho "  =================================================================="\necho "   [ CODEC ]   FREQ 140.85                     PTT  ##############"\necho "  =================================================================="\necho\necho "       S  H  A  D  O  W     M  O  S  E  S     ::     W  E  B"\necho\necho "  ------------------------------------------------------------------"\n'
COMUN = '# Lo comparten los scripts de esta carpeta. Se carga con ". app/unix_comun.sh" desde la carpeta del juego.\nexport PYTHONUTF8=1\nexport PYTHONPATH="$DIR/app/tools/unix"\nunset PYTHONHOME\nulimit -n 4096 2>/dev/null\n\ncomo_instalar() {\n  echo\n  echo "  Se instala asi / Install it like this:"\n  echo "    Ubuntu, Debian:  sudo apt install python3 python3-venv nodejs ffmpeg"\n  echo "    Fedora:          sudo dnf install python3 nodejs ffmpeg   (FFmpeg completo: RPM Fusion / full FFmpeg: RPM Fusion)"\n  echo "    Arch:            sudo pacman -S python nodejs ffmpeg"\n  echo "    Mac (Homebrew):  brew install python node ffmpeg"\n  echo\n}\n\nbuscar_python() {\n  if [ -n "$MGS_PY" ]; then PY=$MGS_PY; return 0; fi\n  if [ -x "$DIR/runtime/venv/bin/python" ]; then PY="$DIR/runtime/venv/bin/python"; return 0; fi\n  for c in python3 python3.14 python3.13 python3.12 python3.11 python3.10 python; do\n    if command -v "$c" >/dev/null 2>&1 && "$c" -c \'import sys; sys.exit(0 if sys.version_info >= (3, 10) else 1)\' 2>/dev/null; then\n      PY=$c; return 0\n    fi\n  done\n  echo "  [ ! ]  Falta Python 3.10 o mas nuevo. / Python 3.10 or newer is missing."\n  como_instalar\n  return 1\n}\n\nfaltan_paquetes() { "$PY" -c \'import numpy, PIL, fontTools\' >/dev/null 2>&1 && return 1; return 0; }\n\npreparar_paquetes() {\n  faltan_paquetes || return 0\n  echo "  Faltan numpy, Pillow y fontTools. Se bajan de internet (unos 60 MB) a runtime/venv, sin tocar tu sistema."\n  echo "  numpy, Pillow and fontTools are missing. They are downloaded (about 60 MB) to runtime/venv, without touching your system."\n  printf "  Seguir? / Continue? (s/y = si/yes): "\n  read -r r\n  case "$r" in s|S|y|Y|si|SI|yes|YES) ;; *) return 1 ;; esac\n  "$PY" -m venv "$DIR/runtime/venv" || { echo "  [ ! ]  No se pudo crear runtime/venv. / Could not create runtime/venv."; como_instalar; return 1; }\n  PY="$DIR/runtime/venv/bin/python"\n  "$PY" -m pip install --disable-pip-version-check numpy pillow fonttools || { echo "  [ ! ]  No se pudieron bajar los paquetes. / Could not download the packages."; return 1; }\n  faltan_paquetes && return 1\n  return 0\n}\n\nver_node() {\n  command -v node >/dev/null 2>&1 && node -e \'process.exit(parseInt(process.versions.node) >= 18 ? 0 : 1)\' && return 0\n  echo "  [ ! ]  Falta Node.js 18 o mas nuevo. / Node.js 18 or newer is missing."\n  como_instalar\n  return 1\n}\n\nver_ffmpeg() {\n  if ! command -v ffmpeg >/dev/null 2>&1; then\n    echo "  [ ! ]  Falta FFmpeg. / FFmpeg is missing."\n    como_instalar\n    return 1\n  fi\n  if ! ffmpeg -hide_banner -encoders 2>/dev/null | grep -q libx264 || ! ffmpeg -hide_banner -demuxers 2>/dev/null | grep -q psxstr; then\n    echo "  [ ! ]  Tu FFmpeg no trae libx264 o psxstr, y hacen falta para los videos del juego."\n    echo "         Your FFmpeg lacks libx264 or psxstr, which the game videos need."\n    como_instalar\n    return 1\n  fi\n  return 0\n}\n\n# Arrastrar un archivo a la terminal pega la ruta con comillas o con barras: esto la deja limpia\nlimpiar_ruta() {\n  p=$(printf \'%s\' "$1" | sed -e \'s/^[[:space:]]*//\' -e \'s/[[:space:]]*$//\' -e \'s#^file://##\')\n  case "$p" in\n    \\\'*\\\') p=${p#\\\'}; p=${p%\\\'}; p=$(printf \'%s\' "$p" | sed -e "s/\'\\\\\\\\\'\'/\'/g") ;;\n    \\"*\\") p=${p#\\"}; p=${p%\\"} ;;\n    *) p=$(printf \'%s\' "$p" | sed -e \'s/\\\\\\(.\\)/\\1/g\') ;;\n  esac\n  case "$p" in "~/"*) p="$HOME/${p#\\~/}" ;; esac\n  printf \'%s\' "$p"\n}\n'
INSTALAR = '#!/bin/sh\n# Shadow Moses web: instalar en Linux o Mac.  Uso: sh instalar.sh [disco1.cue] [disco2.cue]\ncd "$(dirname "$0")" || exit 1\nDIR=$(pwd)\n. "$DIR/app/unix_comun.sh"\n' + BANNER + 'echo "  HQ: Snake, me escuchas? / Snake, do you read me?"\necho "  Necesitas TUS discos de Metal Gear Solid para PlayStation, version USA (.bin/.cue)."\necho "  You need YOUR OWN Metal Gear Solid PlayStation discs, USA version (.bin/.cue)."\necho "  Este paquete no trae nada del juego: convierte tus archivos aca, en tu maquina."\necho "  This package has no game files: it converts yours, here on your machine."\necho\nbuscar_python || exit 1\nver_node || exit 1\nver_ffmpeg || exit 1\npreparar_paquetes || exit 1\nmkdir -p "$DIR/config"\n\nconvertir() { "$PY" "$DIR/app/tools/convertir.py" "$@" --trabajo "$DIR/trabajo" --assets "$DIR/datos"; }\n\nD1=${1:-$MGS_DISCO1}\nD2=${2:-$MGS_DISCO2}\nif [ -z "$D1" ] && [ -f "$DIR/config/disco1.txt" ]; then\n  G1=$(cat "$DIR/config/disco1.txt")\n  G2=""; [ -f "$DIR/config/disco2.txt" ] && G2=$(cat "$DIR/config/disco2.txt")\n  if [ -f "$G1" ]; then\n    echo "  Disco 1 / Disc 1:  $G1"\n    [ -n "$G2" ] && echo "  Disco 2 / Disc 2:  $G2"\n    printf "  Seguir con esos? / Continue with those? (s/y = si/yes, otra cosa = elegir de nuevo / anything else = choose again): "\n    read -r r\n    case "$r" in s|S|y|Y|si|SI|yes|YES) D1=$G1; D2=$G2 ;; esac\n  fi\nfi\n\nif [ -z "$D1" ]; then\n  echo "  HQ: Arrastra a esta ventana el DISCO 1 (.cue o .bin), o escribi la ruta, y toca Enter."\n  echo "  HQ: Drag DISC 1 (.cue or .bin) into this window, or type its path, and press Enter."\n  printf "  > "\n  read -r r\n  D1=$(limpiar_ruta "$r")\n  if [ -z "$D1" ]; then echo "  No elegiste ningun archivo. / No file chosen."; exit 1; fi\n  echo\n  echo "  HQ: Ahora el DISCO 2. Si no lo tenes, toca Enter: se juega hasta el cambio de disco."\n  echo "  HQ: Now DISC 2. If you don\'t have it, press Enter: you can play up to the disc change."\n  printf "  > "\n  read -r r\n  D2=$(limpiar_ruta "$r")\nfi\n\nif ! convertir --validar --disco1 "$D1"; then\n  echo\n  echo "  [ ! ]  HQ: Ese no es el disco correcto. / That\'s not the right disc."\n  echo "  Elegi el .cue (o el .bin) de Metal Gear Solid USA, DISCO 1 (SLUS-00594)."\n  echo "  Choose the .cue (or .bin) of Metal Gear Solid USA, DISC 1 (SLUS-00594)."\n  exit 1\nfi\nif [ -n "$D2" ] && ! convertir --validar --disco2 "$D2"; then\n  echo\n  echo "  [ ! ]  HQ: Ese no es el disco correcto. / That\'s not the right disc."\n  echo "  Elegi el .cue (o el .bin) de Metal Gear Solid USA, DISCO 2 (SLUS-00776)."\n  echo "  Choose the .cue (or .bin) of Metal Gear Solid USA, DISC 2 (SLUS-00776)."\n  exit 1\nfi\n\nprintf \'%s\' "$D1" > "$DIR/config/disco1.txt"\nif [ -n "$D2" ]; then printf \'%s\' "$D2" > "$DIR/config/disco2.txt"; else rm -f "$DIR/config/disco2.txt"; fi\necho\necho "  HQ: Convirtiendo (de 5 a 15 minutos): se puede cortar y retomar corriendo este script de nuevo."\necho "  HQ: Converting (5 to 15 minutes): you can stop and resume by running this script again."\nif [ -n "$D2" ]; then\n  convertir --disco1 "$D1" --disco2 "$D2" --base "$DIR/app/base"\nelse\n  convertir --disco1 "$D1" --base "$DIR/app/base"\nfi\nif [ $? -ne 0 ]; then\n  echo\n  echo "  [ ! ]  No se completo la conversion. Corre sh instalar.sh de nuevo para seguir desde donde quedo."\n  echo "         Conversion not completed. Run sh instalar.sh again to resume."\n  exit 1\nfi\necho\necho "  =================================================================="\necho "   MISION CUMPLIDA / MISSION COMPLETE"\necho "  =================================================================="\necho "  Las proximas veces / Next times:  sh jugar.sh"\necho "  La carpeta \\"trabajo\\" (archivos intermedios, ~1,5 GB) se puede borrar; sin ella, sumar el disco 2 despues tarda mas."\necho "  The \\"trabajo\\" folder (intermediate files, ~1.5 GB) can be deleted; without it, adding disc 2 later takes longer."\necho\n[ -n "$MGS_SIN_JUGAR" ] && exit 0\nexec sh "$DIR/jugar.sh"\n'
JUGAR = '#!/bin/sh\n# Shadow Moses web: jugar. Levanta el servidor local y abre el navegador. MGS_PUERTO cambia el puerto; MGS_SIN_NAVEGADOR=1 no lo abre.\ncd "$(dirname "$0")" || exit 1\nDIR=$(pwd)\n. "$DIR/app/unix_comun.sh"\n[ -f "$DIR/datos/discos.json" ] || exec sh "$DIR/instalar.sh"\nver_node || exit 1\nPUERTO=${MGS_PUERTO:-8123}\nURL="http://127.0.0.1:$PUERTO/"\n' + BANNER + 'echo "  SERVIDOR EN LINEA - SOLO EN ESTA MAQUINA / SERVER ONLINE - THIS MACHINE ONLY"\necho "  En esta maquina / On this machine:   $URL"\necho\necho "  Usa Chrome o Edge. / Use Chrome or Edge."\necho "  Casco por cable USB / Headset over USB:  sh casco_usb.sh"\necho "  Dejala abierta mientras jugas; Ctrl+C la apaga. / Keep this window open while playing; Ctrl+C stops it."\necho\nif [ -z "$MGS_SIN_NAVEGADOR" ]; then\n  if command -v open >/dev/null 2>&1; then (sleep 1; open "$URL") &\n  elif command -v xdg-open >/dev/null 2>&1; then (sleep 1; xdg-open "$URL" >/dev/null 2>&1) &\n  fi\nfi\nexec node "$DIR/app/tools/servidor.mjs" "$PUERTO" "$DIR/app/visor" --assets "$DIR/datos"\n'
JUGAR_RED = '#!/bin/sh\n# Shadow Moses web: jugar desde otro aparato de la misma red.\ncd "$(dirname "$0")" || exit 1\nDIR=$(pwd)\n. "$DIR/app/unix_comun.sh"\n[ -f "$DIR/datos/discos.json" ] || exec sh "$DIR/instalar.sh"\nver_node || exit 1\nPUERTO=${MGS_PUERTO:-8123}\nmkdir -p "$DIR/config"\n' + BANNER + 'echo "  [ ! ]  ABIERTO A TU RED / OPEN TO YOUR NETWORK"\necho "  Mientras esta ventana este abierta, cualquiera en esta misma red puede entrar al juego."\necho "  While this window is open, anyone on this same network can open the game."\necho "  Usalo en la red de tu casa, no en un wifi publico. / Use it on your home network, not on public wifi."\necho\necho "  La primera vez el navegador avisa que la conexion no es privada: el certificado lo crea tu propia maquina."\necho "  Toca \\"Avanzado\\" y \\"Continuar\\". / The first time, the browser warns that the connection is not private:"\necho "  the certificate is made by your own machine. Tap \\"Advanced\\" and \\"Proceed\\"."\necho\nexec node "$DIR/app/tools/servidor.mjs" "$PUERTO" "$DIR/app/visor" --assets "$DIR/datos" --red --cert "$DIR/config"\n'
ARCHIVO_CELULAR = '#!/bin/sh\n# Shadow Moses web: junta los datos convertidos en un solo archivo para la app de Android.\ncd "$(dirname "$0")" || exit 1\nDIR=$(pwd)\n. "$DIR/app/unix_comun.sh"\nbuscar_python || exit 1\necho\necho "  HQ: Juntando tus datos en un solo archivo para la app de celular (1 o 2 minutos)."\necho "  HQ: Packing your data into a single file for the phone app (1 or 2 minutes)."\necho\n"$PY" "$DIR/app/tools/archivo_celular.py" "$DIR/datos" "$DIR/MGSweb_datos.mgs" || exit 1\necho\necho "  Copia MGSweb_datos.mgs al celular (por ejemplo, a Descargas) y elegilo en la app."\necho "  Copy MGSweb_datos.mgs to your phone (for example, to Downloads) and choose it in the app."\necho "  Son tus datos, salen de tus discos: no los subas ni los compartas."\necho "  This is your own data, made from your discs: please do not upload or share it."\n'
CASCO = '#!/bin/sh\n# Shadow Moses web: casco por cable USB (Meta Quest o Pico).\nPUERTO=${MGS_PUERTO:-8123}\necho\necho "  Jugar en el casco (Meta Quest o Pico) con el cable USB / Play on the headset over USB"\necho "  -------------------------------------------------------------------------------------"\necho "  1. El casco en modo desarrollador y conectado por USB (acepta el permiso en el casco)."\necho "     Headset in developer mode, connected over USB (accept the prompt in the headset)."\necho "  2. sh jugar.sh abierto en otra ventana. / sh jugar.sh running in another window."\necho\nif ! command -v adb >/dev/null 2>&1; then\n  echo "  Falta adb (Android Platform Tools). / adb (Android Platform Tools) is missing."\n  echo "    Ubuntu, Debian:  sudo apt install adb"\n  echo "    Mac (Homebrew):  brew install android-platform-tools"\n  echo "    https://developer.android.com/tools/releases/platform-tools"\n  exit 1\nfi\nadb devices\nif adb reverse "tcp:$PUERTO" "tcp:$PUERTO"; then\n  echo\n  echo "  Listo: en el casco abri http://127.0.0.1:$PUERTO/"\n  echo "  Done: open http://127.0.0.1:$PUERTO/ in the headset browser"\nelse\n  echo "  No encontre el casco: revisa el cable y el permiso de depuracion USB."\n  echo "  Headset not found: check the cable and USB debugging."\n  exit 1\nfi\n'
LEEME = '==================================================================\n [ CODEC ]   FREQ 140.85                     PTT  ##############\n==================================================================\n\n      S  H  A  D  O  W     M  O  S  E  S     ::     W  E  B\n\n Linux y Mac / Linux and Mac\n https://mgs.ravenlight.net/\n------------------------------------------------------------------\nProyecto de fans, sin fines de lucro. Metal Gear Solid es una marca de Konami; este proyecto no tiene relación con Konami.\nEste paquete NO trae ningún archivo del juego: usa TUS discos de Metal Gear Solid (PlayStation, versión USA).\n\nSIN PROBAR EN APARATOS REALES: este paquete se probó simulando Linux en una PC con Windows, nunca en un Linux ni en una Mac\nde verdad. Si lo probás, contanos en un issue de GitHub qué sistema usaste y cómo te fue.\n\n[1] QUÉ HACE FALTA\nPython 3.10 o más nuevo, Node.js 18 o más nuevo, FFmpeg con libx264, y unos 3 GB libres.\n  Ubuntu, Debian:  sudo apt install python3 python3-venv nodejs ffmpeg\n  Fedora:          sudo dnf install python3 nodejs ffmpeg   (FFmpeg completo: RPM Fusion)\n  Arch:            sudo pacman -S python nodejs ffmpeg\n  Mac (Homebrew):  brew install python node ffmpeg\nSi faltan numpy, Pillow o fontTools, el instalador te ofrece bajarlos a runtime/venv (unos 60 MB), sin tocar tu sistema.\n\n[2] INSTALAR\nAbrí una terminal en esta carpeta y corré:\n  sh instalar.sh\nArrastrá a la ventana el .cue (o el .bin) de cada disco, o escribí la ruta. Convierte todo en tu máquina (de 5 a 15 minutos).\nSi se corta, corré lo mismo y sigue. Sin el disco 2 se juega hasta el cambio de disco.\n\n[3] JUGAR\n  sh jugar.sh\nSe abre el navegador. Usá Chrome o Edge. Dejá la terminal abierta mientras jugás; Ctrl+C apaga el servidor.\n\n[4] OTROS APARATOS\n  sh jugar_en_red.sh            otro aparato de la misma red, por wifi. Usalo en tu casa, no en un wifi público.\n  sh casco_usb.sh               navegador de un Quest o Pico por cable USB (necesita adb)\n  sh armar_archivo_celular.sh   arma MGSweb_datos.mgs para la app de Android\nPara VR desde la propia máquina, Linux y Mac no tienen Quest Link: usá el navegador del casco.\n\n------------------------------------------------------------------\nNOT TESTED ON REAL DEVICES: this package was tested by simulating Linux on a Windows PC, never on a real Linux box or Mac.\nIf you try it, please tell us in a GitHub issue which system you used and how it went.\n\n[1] WHAT YOU NEED\nPython 3.10 or newer, Node.js 18 or newer, FFmpeg with libx264, and about 3 GB free.\nInstall commands are listed above. If numpy, Pillow or fontTools are missing, the installer offers to download them to\nruntime/venv (about 60 MB), without touching your system.\n\n[2] INSTALL\nOpen a terminal in this folder and run:\n  sh instalar.sh\nDrag the .cue (or .bin) of each disc into the window, or type its path. Everything is converted on your machine (5 to 15 minutes).\nIf it stops, run it again to resume. Without disc 2 you can play up to the disc change.\n\n[3] PLAY\n  sh jugar.sh\nYour browser opens. Use Chrome or Edge. Keep the terminal open while playing; Ctrl+C stops the server.\n\n[4] OTHER DEVICES\n  sh jugar_en_red.sh            another device on the same network, over wifi. Use it at home, not on public wifi.\n  sh casco_usb.sh               Quest or Pico browser over USB (needs adb)\n  sh armar_archivo_celular.sh   builds MGSweb_datos.mgs for the Android app\nFor VR, Linux and Mac have no Quest Link: use the headset browser.\n\nLos nombres de funciones y tablas del conversor (tools/names.txt, tools/tablas_ref.json) salen del proyecto de la\ncomunidad FoxdieTeam/mgs_reversing: https://github.com/FoxdieTeam/mgs_reversing\n\nFeniXVOID · Project Ravenlight\n'
SCRIPTS = {'instalar.sh': INSTALAR, 'jugar.sh': JUGAR, 'jugar_en_red.sh': JUGAR_RED, 'armar_archivo_celular.sh': ARCHIVO_CELULAR, 'casco_usb.sh': CASCO}
